        "term": "bridging",
        "description": "Bridging involves transferring assets from one blockchain to another. This process often requires locking tokens on the original chain and minting equivalent tokens on the destination chain. Popular bridging solutions include Wormhole (multi-chain), Synapse Protocol (cross-chain swaps), and Polygon's PoS Bridge (Ethereum <> Polygon).",
        "use_cases": "Moving ETH from Ethereum to Arbitrum or USDC from Avalanche to Polygon.",
        "examples": ["Wormhole", "Synapse Protocol", "Polygon PoS Bridge"]
      },
      {
        "term": "sending funds",
        "description": "Sending funds is the straightforward transfer of cryptocurrencies within the same blockchain network (e.g., sending ETH from one Ethereum wallet to another). This requires only a recipient address and network fees (gas). No conversion or cross-chain interoperability is involved.",
        "examples": ["MetaMask transfers", "Ledger Live transactions"]
      }
    ],
    "comparison": {
      "key_differences": [
        {
          "aspect": "Blockchain scope",
